import {writeSite,finish,photo as img,link,eyebrow as eye,heading as head,stats,quote,faq,cards,form,select,date,nav} from './build-lib.mjs';

writeSite({id:6,folder:'06-fitness',brand:'FORGE ATHLETICS',industry:'Fitness & Training',description:'Built through effort. Strength, conditioning and a community that shows up.',category:'Lifestyle',fonts:['Barlow Condensed','Archivo'],color:'#171717',body:`
${nav('FORGE<span>ATHLETICS</span>',[['The training','programs'],['Your coaches','coaches'],['Timetable','schedule']],['Find your membership','membership'],'forge-nav')}
<main id="main"><section class="hero forge-hero">${img('gym-hero','Athlete training with dumbbells in a dedicated gym','forge-backdrop',true)}<div class="wrap forge-title">${eye('No shortcuts. Just showing up.')}<h1>YOU’RE NOT<br>DONE <em>YET.</em></h1><p>Find your next level. Then build the one after that.<br>Expert coaching. Real progress. Your people.</p>${link('Find your first session','#schedule')}<span class="hero-stamp">STRONGER<br>TOGETHER.<b>F/A</b></span></div><div class="forge-ribbon"><span>STRENGTH</span><span>●</span><span>CONDITIONING</span><span>●</span><span>COMMUNITY</span><span>●</span><span>CONSISTENCY</span></div></section>
<section class="section wrap" id="programs"><div class="forge-heading">${head('01 / Find your edge','TRAIN WITH<br>INTENTION.')}<p>Whatever your starting point,<br>we’ll meet you there.</p></div><div class="program-grid">${[['01','STRENGTH','Build a foundation that carries into everything you do. Progressive lifting, great form, serious support.','45 MIN / ALL LEVELS'],['02','ENGINE','Go further without burning out. Smart conditioning that challenges you at your own pace.','50 MIN / ALL LEVELS'],['03','HYBRID','Strength meets stamina. Purposeful sessions for those who like a little bit of everything.','60 MIN / INTERMEDIATE']].map(([n,t,d,m])=>`<article><span>${n}</span><h3>${t}</h3><p>${d}</p><div>${m}</div><a href="#schedule" aria-label="See ${t} sessions">↗</a></article>`).join('')}</div></section>
<section class="forge-manifesto"><div class="wrap split">${img('gym-detail','Focused strength training in the Forge concept facility')}<div>${eye('Your work. Our commitment.')}<h2>THE HARDEST<br>PART IS<br><em>WALKING IN.</em></h2><p>After that, you’re one of us. We learn your name, understand your goals and give you a plan you can actually stick with.</p><div class="facility-tags"><span>24 lifting stations</span><span>Recovery studio</span><span>Open gym</span><span>Small group coaching</span></div></div></div></section>
<section class="section wrap" id="schedule"><div class="forge-heading">${head('02 / Make the time','YOUR NEXT SESSION.')}<div class="tabs" role="group" aria-label="Training day">${['Monday','Tuesday','Wednesday','Thursday','Friday'].map((d,i)=>`<button class="pill" data-day="${i}" aria-pressed="${i===0}">${d.slice(0,3)}</button>`).join('')}</div></div><div id="class-list" aria-live="polite"></div><p class="schedule-note">Sample weekly timetable · All sessions coached · Arrive 10 minutes early</p></section>
<section class="section forge-memberships" id="membership"><div class="wrap">${head('03 / Commit to yourself','PUT YOURSELF<br>ON THE CALENDAR.')}<div class="membership-grid">${[['OPEN','79','Open gym access|Training app|Monthly check-in'],['ALL IN','129','Unlimited coached classes|Full gym access|Recovery studio'],['PERSONAL','249','4 private sessions / month|Individual training plan|Everything in All In']].map(([t,p,l],i)=>`<button class="membership-card ${i===1?'chosen':''}" data-membership="${t}" aria-pressed="${i===1}"><span>${i===1?'YOUR NEXT LEVEL':'YOUR COMMITMENT'}</span><h3>${t}</h3><div class="member-price">$${p}<small> / MONTH</small></div><ul>${l.split('|').map(s=>`<li>✓ ${s}</li>`).join('')}</ul><span class="choose-label">${i===1?'Selected ✓':'Choose membership ↗'}</span></button>`).join('')}</div><div class="membership-selection"><p id="membership-choice" role="status">ALL IN selected. Your commitment, your pace.</p>${link('Explore this membership','#join')}</div></div></section>
<section class="section wrap" id="coaches">${head('04 / In your corner','COACHES WHO CARE.')}<div class="coach-grid"><article><span>01 / STRENGTH</span><h3>MARCUS REED</h3><p>Patient coaching. Precise technique. Ten years of helping people surprise themselves.</p></article><article><span>02 / CONDITIONING</span><h3>JESS PARK</h3><p>A firm believer that good energy and smart programming belong in the same session.</p></article><article><span>03 / MOVEMENT</span><h3>DANIEL OKAFOR</h3><p>Building the mobility, confidence and consistency to keep you moving for years.</p></article></div></section>
<section class="forge-results"><div class="wrap">${stats([['850+','Members showing up'],['45','Coached sessions every week'],['12','Experienced coaches'],['ONE','Community behind you']])}</div></section>
<section class="section wrap">${quote('I came for the training. I stayed because someone always notices when I show up.','Sam R.','Forge member for 18 months')}</section>
<section class="section wrap split" id="join"><div>${head('05 / Start where you are','YOUR DAY ONE<br>STARTS HERE.','Meet a coach, explore the space, and find a rhythm that works for you.')}</div>${form('YOUR FIRST VISIT',select('Your membership',['ALL IN','OPEN','PERSONAL'],'membership')+date(),'Preview my visit')}</section></main>`,css:`
:root{--bg:#161717;--ink:#efefec;--accent:#f45d36;--line:#ffffff25;--panel:#222323;--body:'Archivo',sans-serif;--display:'Barlow Condensed',sans-serif;--weight:700;--button-ink:#101111}.forge-nav{position:absolute;left:5%;right:5%;width:90%;border-bottom:1px solid #ffffff40;color:white;min-height:95px}.forge-nav .brand{font:700 34px/.8 var(--display);font-style:italic;display:block}.forge-nav .brand span{display:block;font:400 8px var(--body);letter-spacing:.32em;margin-top:8px}.forge-nav nav{font-size:12px}.forge-nav .nav-cta{background:var(--accent);color:#171717;border:0}.forge-hero{position:relative;min-height:850px;display:flex;align-items:center;padding-top:95px}.forge-backdrop{position:absolute;inset:0;height:100%;filter:brightness(.43);object-position:50% 35%}.forge-title{position:relative;padding:60px 0 110px}.forge-title h1{font-size:clamp(5rem,10.5vw,12rem);line-height:.83;letter-spacing:-.025em;font-style:italic}.forge-title h1 em{color:var(--accent)}.forge-title p:not(.eyebrow){font-size:14px;line-height:1.8;margin-top:30px}.hero-stamp{position:absolute;right:25px;bottom:140px;border:2px solid #ffffffa0;border-radius:50%;height:145px;width:145px;display:flex;flex-direction:column;align-items:center;justify-content:center;font:700 22px/.95 var(--display);transform:rotate(12deg);text-align:center}.hero-stamp b{font-size:35px;margin-top:10px;color:var(--accent)}.forge-ribbon{position:absolute;bottom:0;left:0;right:0;display:flex;justify-content:space-around;gap:25px;overflow:hidden;background:var(--accent);padding:20px;color:#171717;font:700 23px var(--display);letter-spacing:.03em}.forge-ribbon>span{white-space:nowrap}.forge-heading{display:flex;justify-content:space-between;align-items:end;gap:35px}.forge-heading h2{font-size:clamp(3.5rem,5.5vw,6rem);line-height:.9}.forge-heading>p{margin-bottom:42px;font-size:14px;color:#999}.program-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:2px}.program-grid article{background:#232424;padding:35px;position:relative;transition:background .3s}.program-grid article:hover{background:#2c2e2c}.program-grid article>span{font-size:12px;color:var(--accent)}.program-grid h3{font-size:48px;margin:35px 0 20px}.program-grid p{font-size:13px;color:#a1a6a1;line-height:1.9}.program-grid article>div{font-size:10px;margin-top:45px;color:#aaa}.program-grid a{position:absolute;right:25px;top:25px;font-size:25px}.forge-manifesto{background:#e8e8e1;color:#20211f;padding:70px 0}.forge-manifesto h2{font-size:clamp(3.5rem,5.5vw,6.5rem);line-height:.92}.forge-manifesto h2 em{color:#ed5834;font-style:italic}.forge-manifesto img{height:600px;filter:grayscale(1)}.forge-manifesto p{font-size:14px}.facility-tags{display:flex;flex-wrap:wrap;gap:10px;margin-top:25px}.facility-tags span{font-size:10px;border:1px solid #0003;padding:8px 12px}.forge-heading .tabs{margin-bottom:42px}.forge-heading .pill{border-radius:0;min-width:55px}.forge-heading .pill[aria-pressed=true]{background:var(--accent);color:#171717;border-color:var(--accent)}.class-row{display:grid;grid-template-columns:100px 1fr 1fr 120px auto;align-items:center;gap:30px;padding:25px 0;border-bottom:1px solid var(--line)}.class-row h3{font-size:29px}.class-row>span{font-size:12px;color:#aaa}.class-row .class-time{font-size:19px;color:var(--ink)}.class-row button{background:none;border:1px solid var(--line);padding:10px 20px;font-size:12px}.schedule-note{font-size:11px;color:#777;margin-top:24px}.forge-memberships{background:#262725}.membership-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.membership-card{display:block;text-align:left;border:1px solid #fff3;background:transparent;color:#ddd;padding:30px;transition:.25s}.membership-card.chosen{background:var(--accent);color:#171717;border-color:var(--accent);transform:translateY(-8px)}.membership-card>span{font-size:10px;letter-spacing:.1em}.membership-card h3{font-size:45px;margin-top:25px}.member-price{font:700 64px var(--display);margin:20px 0}.member-price small{font:10px var(--body)}.membership-card ul{list-style:none;padding:0;line-height:2.8;font-size:12px;margin:25px 0 40px}.choose-label{border-top:1px solid currentColor;display:block;padding-top:20px}.membership-selection{display:flex;align-items:center;justify-content:space-between;gap:25px;margin-top:30px}.membership-selection p{font-size:12px}.coach-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:35px}.coach-grid article{border-top:1px solid var(--line);padding-top:22px}.coach-grid span{color:var(--accent);font-size:10px}.coach-grid h3{font-size:35px;margin:35px 0 20px}.coach-grid p{font-size:13px;color:#999}.forge-results{background:var(--accent);color:#171717}.forge-results .stats{border:0;padding:45px 0}.forge-results .stats strong{font-size:60px}.quote blockquote{font-size:2.8rem}.forge-hero .button:hover{transform:skewX(-5deg)}@media(max-width:760px){.forge-hero{min-height:800px}.forge-title{padding:50px 0 100px}.forge-title h1{font-size:6rem}.forge-backdrop{object-position:65% center}.hero-stamp{display:none}.forge-ribbon{justify-content:start;gap:25px;padding:15px;font-size:21px}.forge-heading{display:block}.forge-heading>p{margin-top:-20px}.program-grid,.membership-grid,.coach-grid{grid-template-columns:1fr;gap:20px}.forge-manifesto img{height:380px}.forge-manifesto .split>div{padding-top:15px}.forge-heading .tabs{margin-top:-15px;margin-bottom:25px}.class-row{grid-template-columns:65px 1fr auto;gap:15px}.class-row>span:nth-child(3){grid-column:2;font-size:11px}.class-row>span:nth-child(4){display:none}.class-row button{grid-column:3;grid-row:1/3;padding:10px 14px;font-size:10px}.class-row h3{font-size:25px}.class-row .class-time{font-size:15px}.membership-card.chosen{transform:none}.membership-selection{align-items:start;flex-direction:column}.forge-results .stats strong{font-size:48px}.quote blockquote{font-size:2.2rem}.forge-nav nav{background:#161717;color:#fff}}
`,js:`
const schedule=[[['06:00','STRENGTH','Marcus Reed','45 min'],['07:15','ENGINE','Jess Park','50 min'],['12:00','HYBRID','Daniel Okafor','60 min'],['18:00','STRENGTH','Marcus Reed','45 min']],[['06:30','ENGINE','Jess Park','50 min'],['12:00','MOBILITY','Daniel Okafor','40 min'],['17:30','HYBRID','Marcus Reed','60 min']],[['06:00','STRENGTH','Marcus Reed','45 min'],['07:15','ENGINE','Jess Park','50 min'],['18:00','HYBRID','Daniel Okafor','60 min']],[['06:30','MOBILITY','Daniel Okafor','40 min'],['12:00','STRENGTH','Marcus Reed','45 min'],['18:30','ENGINE','Jess Park','50 min']],[['06:00','HYBRID','Marcus Reed','60 min'],['07:15','STRENGTH','Jess Park','45 min'],['17:30','COMMUNITY SESSION','All coaches','60 min']]];
function renderClasses(day){$('#class-list').innerHTML=schedule[day].map(([time,title,coach,length])=>'<article class="class-row"><span class="class-time">'+time+'</span><h3>'+title+'</h3><span>'+coach+'</span><span>'+length+'</span><button data-session="'+title+' at '+time+'">Explore ↗</button></article>').join('');$$('[data-session]').forEach(button=>button.addEventListener('click',()=>showDialog(button.dataset.session,'<p>Expert-led training with room to work at your own pace. Bring water, comfortable training clothes and a little curiosity.</p><p>This sample timetable demonstrates a class booking experience. No place is reserved.</p><a href="#join" class="button">Plan your first visit ↗</a>')));}
renderClasses(0);$$('[data-day]').forEach(button=>button.addEventListener('click',()=>{$$('[data-day]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));renderClasses(Number(button.dataset.day));}));$$('[data-membership]').forEach(button=>button.addEventListener('click',()=>{$$('[data-membership]').forEach(b=>{b.classList.toggle('chosen',b===button);b.setAttribute('aria-pressed',String(b===button));$('.choose-label',b).textContent=b===button?'Selected ✓':'Choose membership ↗';});$('#membership-choice').textContent=button.dataset.membership+' selected. Your commitment, your pace.';$('select[name="membership"]').value=button.dataset.membership;}));
`});

writeSite({id:7,folder:'07-luxury-resort',brand:'AZURE COVE',industry:'Luxury Resort',description:'An unhurried island escape, somewhere between the sky and the sea.',category:'Hospitality',fonts:['Playfair Display','DM Sans'],color:'#edf2ed',body:`
${nav('AZURE COVE',[['Stay','stays'],['Discover','experiences'],['Taste','dining']],['Your island escape','booking'],'resort-nav','≈')}
<main id="main"><section class="hero resort-hero">${img('resort-aerial','Turquoise ocean and overwater villas on a tropical island','',true)}<div class="resort-hero-copy">${eye('A private island. A world of your own.')}<h1>Somewhere<br><em>you can just be.</em></h1><p>Let the ocean set the pace.</p><a href="#welcome" class="scroll-circle" aria-label="Discover Azure Cove">↓</a></div><span class="resort-coordinate">MALDIVES / 04°17′ N 073°25′ E</span></section><form id="stay-search" class="stay-search wrap"><label>Arrive<input type="date" name="arrival" required></label><label>Depart<input type="date" name="departure" required></label><label>Your party<select name="guests"><option>2 guests</option><option>3 guests</option><option>4 guests</option></select></label><button class="button">Find your escape ↗</button><p id="stay-result" role="status"></p></form>
<section class="section wrap resort-welcome" id="welcome">${eye('Welcome to Azure Cove')}<h2>Less of everything.<br><em>More of what matters.</em></h2><p>Warm sand beneath your feet. A book you finally have time to finish. Days with no particular plan. Tucked into the blue of the Indian Ocean, Azure Cove is an invitation to rediscover the simple luxury of being here.</p><span class="wave-line" aria-hidden="true">∿ ∿ ∿</span></section>
<section class="section wrap" id="stays"><div class="resort-heading">${head('Your island home','Wake up somewhere<br><em>extraordinary.</em>')}<p>Considered spaces.<br>Endless horizons.</p></div><div class="stay-grid"><article class="image-card">${img('resort-hero','A serene pool at a tropical luxury resort')}<div><span>01 / BY THE WATER</span><h3>The Lagoon Suite</h3><p>Open to the breeze. Steps from the blue. A quiet retreat for two, with a private deck and a view that never gets old.</p><div class="stay-meta"><span>110 m² · 2 guests</span><span>From $680 / night</span></div><button class="text-link" data-room="The Lagoon Suite">Discover your suite ↗</button></div></article><article class="image-card">${img('resort-detail','Palm-lined resort terrace and pool')}<div><span>02 / AMONG THE PALMS</span><h3>The Garden Residence</h3><p>Space to be together, room to be yourself. Two bedrooms, a private plunge pool and gardens full of birdsong.</p><div class="stay-meta"><span>220 m² · 4 guests</span><span>From $940 / night</span></div><button class="text-link" data-room="The Garden Residence">Discover your residence ↗</button></div></article></div></section>
<section class="resort-experiences" id="experiences"><div class="wrap split"><div>${head('Follow your curiosity','Do everything.<br>Or absolutely nothing.','A sunrise on the water. A reef alive with color. A treatment beneath the palms. Your days here belong entirely to you.')}<div class="experience-links"><button data-experience="Beneath the blue">01 <span>Beneath the blue</span> ↗</button><button data-experience="The art of slowing down">02 <span>The art of slowing down</span> ↗</button><button data-experience="Sail into the sunset">03 <span>Sail into the sunset</span> ↗</button></div></div>${img('resort-aerial','An aerial view of clear water surrounding island villas')}</div></section>
<section class="section wrap split" id="dining">${img('dining-detail','A beautifully prepared seasonal dish')}<div>${head('A taste of the island','Fresh from the ocean.<br>Close to the heart.','At Tide, our open-air restaurant, the menu follows the morning catch and the island garden. Long lunches turn into unhurried evenings. There is always time for one more course.')}<p>Breakfast 7–11 am · Lunch 12–3 pm<br>Dinner 6:30–10 pm · Sunset bar from 4 pm</p></div></section>
<section class="section resort-moments"><div class="wrap">${head('The little luxuries','All the space you need.')}${cards([['RESTORE','Island spa','Three garden treatment rooms, guided breathwork and daily sunrise yoga.'],['EXPLORE','Ocean adventures','Guided snorkeling, paddleboards and a small fleet of sailing boats.'],['BELONG','Thoughtful hospitality','An island host, private transfers and details remembered from day one.']])}</div></section>
<section class="section wrap">${quote('For the first time in years, we forgot to check the time. That tells you everything.','Olivia & Nathan','Seven wonderful days in the cove')}</section>
<section class="section wrap split" id="booking"><div>${head('The island is calling','A little further away.<br>A little closer to yourself.','Your escape begins with a scenic 35-minute seaplane journey from Malé. We take care of the details, so you can start slowing down.')}<p>North Malé Atoll · Maldives<br>Private island transfers arranged with every stay.</p></div>${form('Imagine your stay',date('Arrival date')+select('Your island home',['The Lagoon Suite','The Garden Residence'],'room')+select('Length of stay',['3 nights','5 nights','7 nights','10 nights'],'nights'),'Preview my escape')}</section></main>`,css:`
:root{--bg:#f5f5ed;--ink:#2c504e;--accent:#2c625e;--line:#2c504e33;--panel:#eaf0e8;--body:'DM Sans',sans-serif;--display:'Playfair Display',serif;--weight:400}.resort-nav{position:absolute;left:5%;width:90%;color:white;min-height:110px;border-bottom:1px solid #fff5;--line:#ffffff80}.resort-nav .brand{font:400 21px var(--display);letter-spacing:.08em}.resort-nav nav{font-size:12px}.resort-hero{height:870px;position:relative;color:white}.resort-hero>img{height:100%;filter:brightness(.65)}.resort-hero-copy{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:100px 25px}.resort-hero h1{font-size:clamp(4rem,6.7vw,7rem);line-height:1.12;letter-spacing:-.055em;text-shadow:0 3px 25px #0002}.resort-hero h1 em{font-weight:400}.resort-hero .eyebrow{font-size:10px;letter-spacing:.2em}.resort-hero p:not(.eyebrow){font-size:14px;margin:28px 0}.scroll-circle{display:grid;place-items:center;width:48px;height:48px;border:1px solid #fff8;border-radius:50%;margin-top:25px;font-size:22px}.resort-coordinate{position:absolute;bottom:75px;right:5%;font-size:9px;letter-spacing:.12em}.stay-search{position:relative;z-index:2;display:grid;grid-template-columns:1fr 1fr 1fr auto;padding:30px 35px;background:var(--bg);gap:28px;margin-top:-38px;border-bottom:1px solid var(--line);box-shadow:0 14px 40px #143a3510;align-items:end}.stay-search input,.stay-search select{border:0;border-bottom:1px solid var(--line);padding-left:0;background:none;font-size:13px}.stay-search label{font-size:11px}.stay-search .button{height:52px}.stay-search>p{grid-column:1/-1;font-size:13px}.stay-search>p:empty{display:none}.resort-welcome{text-align:center;max-width:870px}.resort-welcome h2{line-height:1.25}.resort-welcome>p:not(.eyebrow){font-size:15px;max-width:630px;margin:28px auto;color:#657e76}.wave-line{font-size:38px;letter-spacing:.1em;color:#a8b5a5;display:block;margin-top:30px}.resort-heading{display:flex;justify-content:space-between;align-items:end}.resort-heading h2{line-height:1.2}.resort-heading>p{font-size:13px;color:#7f9388;margin-bottom:42px}.stay-grid{display:grid;grid-template-columns:1fr 1fr;gap:65px}.stay-grid>article:nth-child(2){margin-top:110px}.stay-grid img{height:550px}.stay-grid>article>div{padding:28px 0}.stay-grid>article>div>span{font-size:10px;letter-spacing:.12em}.stay-grid h3{font-size:2rem;margin:18px 0}.stay-grid p{font-size:14px;line-height:1.9;opacity:.7}.stay-meta{display:flex;justify-content:space-between;border-block:1px solid var(--line);padding:15px 0;margin:25px 0;font-size:11px}.stay-grid button{border:0;border-bottom:1px solid var(--line);background:none;font-size:12px}.resort-experiences{background:#e6ede4;padding:100px 0}.resort-experiences img{height:580px;border-radius:48% 48% 0 0;object-position:65% center}.experience-links button{display:flex;align-items:center;gap:20px;width:100%;background:none;border:0;border-bottom:1px solid var(--line);padding:19px 0;text-align:left;font-size:11px}.experience-links button span{flex:1;font:20px var(--display)}#dining>img{height:560px}#dining p{font-size:14px}.resort-moments{background:#2d5651;color:#f2f2e7;--line:#fff3}.resort-moments .cards article{border:0;border-top:1px solid var(--line);padding:28px 0}.resort-moments h3{font-size:26px}.resort-moments .cards{gap:50px}.quote{max-width:840px}.quote blockquote{font-size:2.4rem;line-height:1.5}.button{padding:17px 25px}.resort-welcome{animation:softArrival 1.4s}@keyframes softArrival{from{opacity:0}to{opacity:1}}@media(max-width:760px){.resort-nav{min-height:88px}.resort-nav .brand{font-size:17px}.resort-hero{height:760px}.resort-hero h1{font-size:3.7rem}.resort-hero>img{object-position:62% center}.resort-coordinate{bottom:70px;font-size:8px}.stay-search{grid-template-columns:1fr 1fr;gap:20px;padding:24px}.stay-search .button{height:auto;font-size:11px;padding:14px}.resort-heading{display:block}.resort-heading>p{margin-top:-20px}.stay-grid{grid-template-columns:1fr;gap:35px}.stay-grid>article:nth-child(2){margin:0}.stay-grid img{height:430px}.resort-experiences{padding:60px 0}.resort-experiences img{height:460px}.resort-moments .cards{gap:25px}.quote blockquote{font-size:1.9rem}.resort-welcome>p:not(.eyebrow){font-size:14px}.resort-hero-copy{padding-top:90px}}
`,js:`
$('#stay-search').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);const start=new Date(f.get('arrival')+'T12:00:00'),end=new Date(f.get('departure')+'T12:00:00');if(end<=start){$('#stay-result').textContent='Please choose a departure after your arrival.';return;}const nights=Math.round((end-start)/86400000);$('#stay-result').textContent=nights+' nights for '+f.get('guests')+'. Explore the Lagoon Suite from $680/night or the Garden Residence from $940/night. Sample rates; no live availability is checked.';$('#booking input[name="date"]').value=f.get('arrival');});
$('input[name="arrival"]').addEventListener('change',e=>{const day=new Date(e.target.value+'T12:00:00');day.setDate(day.getDate()+1);$('input[name="departure"]').min=[day.getFullYear(),String(day.getMonth()+1).padStart(2,'0'),String(day.getDate()).padStart(2,'0')].join('-');});
$$('[data-room]').forEach(b=>b.addEventListener('click',()=>showDialog(b.dataset.room,'<p>Quiet natural materials, generous indoor-outdoor spaces, an ocean-inspired bathroom and thoughtful island touches.</p><p>Included: daily breakfast, island host, snorkeling equipment and return shared boat transfers from the seaplane platform.</p><a class="button" href="#booking">Imagine your stay ↗</a>')));const experiences={'Beneath the blue':'Explore the house reef with a marine guide. Small groups, unhurried swims and a closer look at the life beneath the surface.','The art of slowing down':'A garden spa ritual, gentle movement at sunrise and time to do a little less. Treatments are tailored around how you want to feel.','Sail into the sunset':'Step aboard our island dhoni for a quiet evening on the water, with a small picnic and a front-row seat to the changing sky.'};$$('[data-experience]').forEach(b=>b.addEventListener('click',()=>showDialog(b.dataset.experience,'<p>'+experiences[b.dataset.experience]+'</p>')));
`});

writeSite({id:8,folder:'08-fashion',brand:'ATELIER NOIR',industry:'Fashion & Apparel',description:'Modern essentials. Considered silhouettes. A wardrobe beyond the season.',category:'Lifestyle',fonts:['Bodoni Moda','Inter'],color:'#f0efeb',body:`
<div class="fashion-announcement">A STUDY IN EVERYDAY ELEGANCE — COLLECTION 06</div>${nav('A / N',[['New arrivals','arrivals'],['Collections','collections'],['The journal','journal']],null,'fashion-nav')}<button class="wishlist-nav" id="wishlist-button" aria-label="View saved pieces">Wishlist (<span id="wish-count">0</span>)</button>
<main id="main"><section class="hero fashion-hero"><h1>ATELIER NOIR</h1><div class="campaign"><div class="campaign-photo">${img('fashion-hero','Editorial fashion portrait in a studio','',true)}</div><div class="campaign-copy"><span>THE NEW COLLECTION / 06</span><h2>The art of<br><em>less.</em></h2><p>Quiet confidence.<br>Uncompromising expression.</p>${link('Explore the collection','#arrivals','text-link')}<span class="campaign-season">AUTUMN / WINTER 2026</span></div><div class="campaign-secondary">${img('fashion-detail','Black and white fashion study','',true)}</div></div><div class="fashion-caption"><span>FORM. TEXTURE. INTENTION.</span><span>Clothes to live in. A point of view to make your own.</span><span>01 — 06</span></div></section>
<section class="section wrap" id="arrivals"><div class="fashion-heading">${head('Selected pieces','New perspectives.')}<div class="tabs" data-filter-group="product-grid"><button class="pill" data-filter="all" aria-pressed="true">All pieces</button><button class="pill" data-filter="tailoring" aria-pressed="false">Tailoring</button><button class="pill" data-filter="essentials" aria-pressed="false">Essentials</button></div></div><div class="fashion-products" id="product-grid">${[['fashion-hero','The Column Coat','Warm sand','$420','tailoring'],['fashion-detail','The Sculpted Knit','Ink black','$185','essentials'],['fashion-hero','The Fluid Trouser','Stone','$210','tailoring'],['fashion-detail','The Form Top','Soft ivory','$125','essentials']].map(([im,t,c,p,cat],i)=>`<article data-category="${cat}"><div class="product-photo">${img(im,t+' editorial styling','product-img product-crop-'+i)}<button class="wish" aria-label="Save ${t}" aria-pressed="false" data-wish="${t}">+</button><button class="quick-view" data-product="${i}">Explore piece ↗</button></div><div class="product-title"><h3>${t}</h3><span>${p}</span></div><p>${c}</p></article>`).join('')}</div></section>
<section class="fashion-collection" id="collections"><div>${img('fashion-detail','Monochrome fashion editorial')}<span>VOLUME 06 — THE STUDY</span></div><div>${eye('A considered wardrobe')}<h2>Nothing extra.<br><em>Everything<br>considered.</em></h2><p>A conversation between structure and softness. Pieces that hold their own, and work beautifully together.</p>${link('View selected pieces','#arrivals','text-link')}</div></section>
<section class="section wrap fashion-journal" id="journal"><div class="fashion-heading">${head('Notes from the atelier','Beyond the silhouette.')}<span>THE JOURNAL / 2026</span></div><div class="journal-grid"><article><span>01 / MATERIAL</span><h3>The feeling of a fabric.</h3><p>Why we begin every collection with the things you can touch. Natural fibers, honest texture and a little unexpected softness.</p><button class="text-link" data-detail="journal-1" data-title="The feeling of a fabric">Read the story ↗</button><template id="journal-1"><p>Before a sketch, there is a swatch. Our process starts with how a fabric falls, moves and feels against the skin.</p><p>For Collection 06, we explored dry wool, fine cotton and fluid viscose. Each was chosen for a quiet quality that gets better with wear. The result is a wardrobe defined as much by feeling as by form.</p></template></article><article><span>02 / PERSPECTIVE</span><h3>A wardrobe, not a moment.</h3><p>Designing for the way we live, and the people we become. On choosing well and wearing something your own way.</p><button class="text-link" data-detail="journal-2" data-title="A wardrobe, not a moment">Read the story ↗</button><template id="journal-2"><p>We are interested in pieces that become part of your life. A coat that feels like an old friend. A shirt that works on a Tuesday and feels right on a Sunday.</p><p>Our silhouettes return, evolve and speak to one another across collections. Wear them together, or let them join what you already love.</p></template></article></div></section>
<section class="fashion-story section"><div class="wrap"><span class="atelier-monogram">A/N</span><h2>Made with intention.<br><em>Worn with individuality.</em></h2><p>Atelier Noir is an independent design house built around a simple idea: the most interesting thing about a piece of clothing is the person who wears it.</p></div></section>
<section class="section wrap fashion-newsletter"><div>${eye('A letter, occasionally')}<h2>Inside the atelier.</h2><p>New collections, considered stories, and a closer look.</p></div><form id="fashion-newsletter"><label for="newsletter-email">Your email address</label><div><input id="newsletter-email" type="email" placeholder="Email address" required autocomplete="email"><button type="submit" aria-label="Preview newsletter signup">→</button></div><p id="newsletter-result" role="status">A quieter kind of inbox. Demo signup only.</p></form></section></main>`,css:`
:root{--bg:#f2f1ed;--ink:#262623;--accent:#282824;--line:#d3d1ca;--panel:#e9e8e2;--body:'Inter',sans-serif;--display:'Bodoni Moda',serif;--weight:400}.fashion-announcement{text-align:center;font-size:8px;letter-spacing:.15em;padding:12px;border-bottom:1px solid var(--line)}.fashion-nav{min-height:82px;justify-content:start;gap:100px}.fashion-nav .brand{font:24px var(--display)}.fashion-nav nav{font-size:10px;text-transform:uppercase;letter-spacing:.06em}.wishlist-nav{position:absolute;right:5%;top:67px;border:0;background:none;font-size:11px;padding:8px}.fashion-hero h1{text-align:center;font-size:clamp(4rem,11.8vw,13rem);line-height:1;letter-spacing:-.05em;font-weight:400;white-space:nowrap;padding:12px 0 30px}.campaign{display:grid;grid-template-columns:1fr .85fr .85fr;min-height:650px}.campaign-photo img,.campaign-secondary img{height:100%;min-height:650px;object-position:50% 35%}.campaign-copy{display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:50px 20px;background:#e7e3dc}.campaign-copy>span:first-child{font-size:9px;letter-spacing:.15em}.campaign-copy h2{font-size:clamp(3.4rem,4.9vw,5.5rem);margin:38px 0 0;line-height:1.15}.campaign-copy h2 em{font-weight:400}.campaign-copy p{font-size:12px;line-height:1.9}.campaign-copy .text-link{font-size:10px;margin-top:10px}.campaign-season{font-size:8px;letter-spacing:.15em;margin-top:65px}.campaign-secondary img{filter:grayscale(1)}.fashion-caption{display:flex;justify-content:space-between;gap:20px;font-size:8px;letter-spacing:.1em;padding:25px 5%;border-bottom:1px solid var(--line)}.fashion-caption>span:nth-child(2){letter-spacing:0;text-transform:none}.fashion-heading{display:flex;justify-content:space-between;align-items:end;gap:30px}.fashion-heading .tabs{margin-bottom:42px}.fashion-heading .pill{border:0;border-radius:0;padding:5px 10px;font-size:10px}.fashion-heading .pill[aria-pressed=true]{background:none;color:inherit;text-decoration:underline;text-underline-offset:6px}.fashion-products{display:grid;grid-template-columns:repeat(4,1fr);gap:25px}.product-photo{position:relative;overflow:hidden;background:#ddd}.product-img{height:390px;transition:transform .8s,filter .8s;object-position:50% 30%}.product-photo:hover .product-img{transform:scale(1.05);filter:contrast(1.06)}.product-crop-2{object-position:70% 100%;transform:scale(1.15)}.product-crop-3{object-position:30% 20%;transform:scale(1.1)}.wish{position:absolute;top:12px;right:12px;border:0;background:var(--bg);width:30px;height:30px;border-radius:50%;font-size:18px}.wish[aria-pressed=true]{background:#292925;color:white}.quick-view{position:absolute;bottom:0;left:0;right:0;background:#f2f1eded;border:0;padding:14px;font-size:10px;opacity:0;transform:translateY(100%);transition:.3s}.product-photo:hover .quick-view,.product-photo:focus-within .quick-view{opacity:1;transform:none}.product-title{display:flex;justify-content:space-between;gap:8px;margin:20px 0 9px}.product-title h3{font:400 12px var(--body);letter-spacing:-.03em}.product-title>span{font-size:11px}.fashion-products article>p{font-size:10px;color:#939087}.fashion-collection{display:grid;grid-template-columns:1fr 1fr;background:#dedbd3}.fashion-collection>div:first-child{position:relative}.fashion-collection img{height:790px;filter:grayscale(1)}.fashion-collection>div:first-child>span{position:absolute;bottom:25px;left:30px;color:white;font-size:9px;letter-spacing:.1em}.fashion-collection>div:last-child{display:flex;flex-direction:column;justify-content:center;padding:12%}.fashion-collection h2{font-size:clamp(3.5rem,5vw,5.5rem);line-height:1.15}.fashion-collection p:not(.eyebrow){font-size:13px;margin:30px 0;max-width:340px;line-height:1.9}.fashion-collection .text-link{width:fit-content}.fashion-heading>span{font-size:9px;letter-spacing:.1em;margin-bottom:42px}.journal-grid{display:grid;grid-template-columns:1fr 1fr;gap:70px}.journal-grid article{border-top:1px solid var(--line);padding-top:30px}.journal-grid article>span{font-size:9px;letter-spacing:.1em}.journal-grid h3{font-size:2rem;margin:25px 0 20px}.journal-grid p{font-size:13px;line-height:1.9;opacity:.7}.journal-grid button{background:none;border:0;border-bottom:1px solid var(--line);font-size:11px;margin-top:25px}.fashion-story{text-align:center;background:#e8e5dd}.atelier-monogram{font:55px var(--display);display:block;margin-bottom:35px}.fashion-story h2{line-height:1.3;font-size:3rem}.fashion-story p{margin:30px auto 0;font-size:14px;max-width:550px;line-height:1.9;opacity:.7}.fashion-newsletter{display:grid;grid-template-columns:1fr 1fr;gap:10%;align-items:center}.fashion-newsletter h2{font-size:3rem}.fashion-newsletter p{font-size:12px;margin-top:15px}.fashion-newsletter form>div{display:flex;border-bottom:1px solid var(--ink)}.fashion-newsletter input{border:0;background:transparent;padding-left:0;font-size:14px}.fashion-newsletter button{border:0;background:none;font-size:30px;padding:0 15px}.fashion-newsletter form label{font-size:10px}.fashion-newsletter form p{font-size:10px;opacity:.6}.site-footer .brand{font:26px var(--display)}@media(max-width:760px){.fashion-announcement{font-size:7px}.fashion-nav{min-height:75px;justify-content:space-between}.wishlist-nav{right:24%;top:58px;font-size:10px}.fashion-hero h1{font-size:12vw;padding:15px 0 25px}.campaign{grid-template-columns:1fr 1fr;min-height:0}.campaign-photo img{height:550px;min-height:0;object-position:50% 30%}.campaign-secondary{display:none}.campaign-copy{padding:35px 15px}.campaign-copy h2{font-size:2.8rem;margin-top:28px}.campaign-copy>span:first-child{font-size:7px}.campaign-copy p{font-size:10px}.campaign-copy .text-link{font-size:9px;gap:12px}.campaign-season{font-size:7px;margin-top:35px}.fashion-caption{font-size:7px}.fashion-caption>span:nth-child(2){display:none}.fashion-heading{display:block}.fashion-heading .tabs{margin-top:-15px;margin-bottom:28px}.fashion-products{grid-template-columns:1fr 1fr;gap:30px 15px}.product-img{height:320px}.product-title{flex-direction:column}.product-title h3{font-size:12px}.quick-view{opacity:1;transform:none;font-size:9px;padding:12px}.fashion-collection{grid-template-columns:1fr}.fashion-collection img{height:550px}.fashion-collection>div:last-child{padding:50px 7%}.fashion-collection h2{font-size:3.5rem}.journal-grid{grid-template-columns:1fr;gap:35px}.fashion-heading>span{display:block;margin-top:-15px}.fashion-story h2{font-size:2.4rem}.fashion-newsletter{grid-template-columns:1fr;gap:35px}.fashion-nav nav{font-size:12px}.fashion-nav .nav-toggle{font-size:11px}}@media(max-width:420px){.product-img{height:275px}.campaign-photo img{height:485px}.campaign-copy h2{font-size:2.5rem}.wishlist-nav{right:26%}}
`,js:`
const wishlist=new Set();$$('[data-wish]').forEach(b=>b.addEventListener('click',()=>{const title=b.dataset.wish;if(wishlist.has(title))wishlist.delete(title);else wishlist.add(title);b.setAttribute('aria-pressed',String(wishlist.has(title)));b.textContent=wishlist.has(title)?'✓':'+';$('#wish-count').textContent=wishlist.size;}));$('#wishlist-button').addEventListener('click',()=>showDialog('Your considered pieces',wishlist.size?'<p>'+[...wishlist].join('</p><p>')+'</p><p>Saved for this visit. This concept does not process orders.</p>':'<p>Your wishlist is waiting. Use the + on a piece to keep it close.</p>'));
const pieces=[['The Column Coat','420','Warm sand','A long, considered silhouette with a soft shoulder and a clean, uninterrupted line.'],['The Sculpted Knit','185','Ink black','A soft structure, a considered neckline, and room to move.'],['The Fluid Trouser','210','Stone','An easy drape, a generous leg and a tailored finish.'],['The Form Top','125','Soft ivory','A quiet foundation for an expressive wardrobe.']];$$('[data-product]').forEach(b=>b.addEventListener('click',()=>{const [title,price,color,desc]=pieces[Number(b.dataset.product)];showDialog(title,'<p>'+color+' · $'+price+'</p><p>'+desc+'</p><label>Explore a size<select><option>XS</option><option>S</option><option>M</option><option>L</option><option>XL</option></select></label><p>Illustrative editorial imagery. This collection is a fictional concept; no purchase is processed.</p>');}));$('#fashion-newsletter').addEventListener('submit',e=>{e.preventDefault();$('#newsletter-result').textContent='Thank you. Your email is valid — this demo has not subscribed or sent your details.';});
`});

writeSite({id:9,folder:'09-healthcare',brand:'nova care',industry:'Healthcare',description:'Thoughtful care for the whole you, from people who take the time.',category:'Professional',fonts:['Plus Jakarta Sans','Lora'],color:'#eff5ef',body:`
<div class="nova-top"><span>Good care begins with a conversation.</span><a href="#visit">New here? We’ll help you feel at home →</a></div>${nav('nova care',[['Our care','services'],['Our people','doctors'],['Your visit','visit']],['Let’s find your care','appointment'],'nova-nav','✳')}
<main id="main"><section class="hero nova-hero wrap"><div>${eye('Healthcare, with a human side.')}<h1>You’re a person.<br><em>Not a patient number.</em></h1><p>Care that listens. People who remember your name. A little more time for the things that matter to you.</p><div class="hero-actions">${link('Find your care','#services')}${link('Meet our team','#doctors','text-link')}</div><div class="nova-reassurance"><span>✓ Unhurried appointments</span><span>✓ Care, connected</span></div></div><div class="nova-portrait">${img('health-hero','A welcoming healthcare professional in a white coat','',true)}<div class="care-card"><span class="care-cross">+</span><p><strong>A familiar face.<br>Every step of the way.</strong><small>Care built around you.</small></p></div></div></section>
<section class="nova-quicklinks wrap"><a href="#services"><span>01</span><strong>Find the right care</strong><span>↗</span></a><a href="#doctors"><span>02</span><strong>Meet your care team</strong><span>↗</span></a><a href="#visit"><span>03</span><strong>Plan your first visit</strong><span>↗</span></a></section>
<section class="section wrap" id="services">${head('Here for the everyday. And the unexpected.','A little care goes a long way.')}<div class="care-services">${[['✳','Primary care','A trusted place to start. Ongoing support, routine visits and care that sees the whole picture.','Primary care'],['◡','Mental wellbeing','A comfortable space to talk, find perspective and work toward feeling more like yourself.','Mental wellbeing'],['◎','Women’s health','Thoughtful, personal care through different stages of life, with time for your questions.','Women’s health'],['↗','Specialist care','When you need another perspective, we help connect the next steps in your care.','Specialist care']].map(([icon,t,d,v])=>`<button class="care-service" data-service="${v}"><span class="care-icon">${icon}</span><h3>${t}</h3><p>${d}</p><span class="service-more">Explore care ↗</span></button>`).join('')}</div></section>
<section class="nova-philosophy section"><div class="wrap split">${img('health-detail','A friendly medical professional in a bright clinic')}<div>${head('Care is a relationship.','We make time<br>to understand you.','The best care starts with listening. We bring your questions, your goals and your everyday life into the conversation — then work with you on what comes next.')}<ul class="nova-values"><li>A care team that knows your story</li><li>Clear explanations, without the rush</li><li>Thoughtful follow-up, after your visit</li></ul></div></div></section>
<section class="section wrap" id="doctors"><div class="nova-heading">${head('Good people. Thoughtful care.','Meet the people in your corner.')}<p>Different expertise.<br>The same human approach.</p></div><div class="doctor-grid"><article>${img('health-hero','Illustrative portrait for Dr. Maya Bennett')}<div><h3>Dr. Maya Bennett</h3><p>Primary Care · Family Medicine</p><span>“A good conversation is where I always start.”</span></div></article><article>${img('health-detail','Illustrative portrait for Dr. Aisha Cole')}<div><h3>Dr. Aisha Cole</h3><p>Women’s Health · Preventive Care</p><span>“Every question deserves a thoughtful answer.”</span></div></article><article class="care-team-note"><span class="care-icon">✳</span><h3>Many people.<br>One team.</h3><p>From the first hello to your follow-up call, our coordinators, nurses and clinicians work together around you.</p>${link('Find your care','#appointment','text-link')}</article></div></section>
<section class="section wrap nova-visit" id="visit"><div>${head('A first visit, made easier.','Come as you are.')}<p>Bring your questions, a list of your medications, and any records you’d like us to review. We’ll take it from there.</p><div class="visit-steps"><p><span>01</span>Tell us what brings you in.</p><p><span>02</span>Meet the right member of our team.</p><p><span>03</span>Leave with a clear next step.</p></div></div><div>${faq([['How do I arrange a first visit?','Use the appointment preview below to choose a department and date. This fictional clinic does not offer real appointments; the form demonstrates the intended experience.'],['What should I bring?','In a real care setting, your care team would confirm the details before your visit. This demo illustrates a place for practical patient information.'],['Can I choose who I see?','The design allows people to explore the team, choose a care area and share preferences when requesting a visit.']])}</div></section>
<section class="nova-quote section"><div class="wrap">${quote('I never felt rushed. For the first time in a long time, I felt really heard.','A Nova Care story','Illustrative patient experience')}</div></section>
<section class="section wrap split" id="appointment"><div>${head('A good place to start.','Let’s take the<br>next step, together.','Choose a care area and a time that works for you.')}<p class="nova-address">The Nova House<br>42 Garden Street, Portland<br>Monday–Friday, 8 am–6 pm · Saturday, 9 am–1 pm</p></div>${form('Plan a visit',select('Care area',['Primary care','Mental wellbeing','Women’s health','Specialist care'],'department')+date(),'Preview my appointment')}</section></main>`,css:`
:root{--bg:#f5f7f2;--ink:#234a44;--accent:#285e50;--line:#234a4430;--panel:#e8efe6;--body:'Plus Jakarta Sans',sans-serif;--display:'Plus Jakarta Sans',sans-serif;--weight:500}.nova-top{display:flex;justify-content:space-between;padding:10px 5%;background:#dce9dd;color:#45695c;font-size:10px}.nova-nav .brand{font-size:29px;font-weight:600;letter-spacing:-.06em}.nova-nav .brand-symbol{font-size:32px}.nova-nav nav{font-size:12px}.nova-nav .nav-cta{border-radius:30px;background:var(--accent);color:#fff}.nova-hero{display:grid;grid-template-columns:1.1fr 1fr;gap:8%;align-items:center;padding:50px 0 80px}.nova-hero h1{font-size:clamp(3rem,4.5vw,5.2rem);line-height:1.15;letter-spacing:-.06em}.nova-hero h1 em{font:italic 1em/1.1 'Lora',serif;font-weight:400;color:#6d9178}.nova-hero p:not(.eyebrow){font-size:14px;line-height:1.9;max-width:430px}.nova-hero .button{border-radius:30px;padding:17px 24px}.nova-hero .text-link{border-bottom:0;font-size:12px}.nova-portrait{position:relative;padding:10px 0 30px}.nova-portrait>img{height:600px;border-radius:220px 220px 80px 80px;object-position:48% center}.care-card{position:absolute;bottom:15px;left:-50px;background:#fff8e9;border:1px solid #d9d6c9;border-radius:18px;padding:22px 27px;display:flex;align-items:center;gap:18px;box-shadow:0 15px 30px #26402a0b}.care-cross{width:46px;height:46px;border-radius:50%;background:#e0e9d9;display:grid;place-items:center;font-size:30px;font-weight:400}.care-card p{margin:0!important;line-height:1.5!important;font-size:13px!important}.care-card strong{font-weight:500}.care-card small{display:block;font-size:9px;margin-top:5px;opacity:.6}.nova-reassurance{display:flex;gap:20px;font-size:10px;color:#73907d;margin-top:40px}.nova-quicklinks{display:grid;grid-template-columns:repeat(3,1fr);border-block:1px solid var(--line)}.nova-quicklinks a{display:flex;gap:18px;align-items:center;padding:25px 20px;border-right:1px solid var(--line);font-size:12px}.nova-quicklinks a:first-child{padding-left:0}.nova-quicklinks a:last-child{border:0}.nova-quicklinks strong{font-weight:500;flex:1}.nova-quicklinks span:first-child{font-size:10px;opacity:.5}.care-services{display:grid;grid-template-columns:repeat(4,1fr);gap:20px}.care-service{padding:30px 24px;background:#e9eee3;border:0;border-radius:15px;text-align:left;transition:transform .3s,background .3s}.care-service:nth-child(2){background:#f1e8dd}.care-service:nth-child(3){background:#eee6e7}.care-service:nth-child(4){background:#e3e9ed}.care-service:hover{transform:translateY(-7px)}.care-icon{font:34px 'Lora',serif;display:block;margin-bottom:35px}.care-service h3{font-size:21px;line-height:1.2;margin-bottom:20px}.care-service p{font-size:12px;line-height:1.9;opacity:.7}.service-more{display:block;font-size:11px;margin-top:35px}.nova-philosophy{background:#e8ede2}.nova-philosophy img{height:590px;border-radius:160px 160px 10px 10px;object-position:center 30%}.nova-philosophy h2{font-size:3.5rem;line-height:1.2}.nova-philosophy p{font-size:14px}.nova-values{list-style:none;padding:0;font-size:13px;line-height:2.7}.nova-values li:before{content:'✓';margin-right:15px;color:#79967b}.nova-heading{display:flex;align-items:end;justify-content:space-between;gap:35px}.nova-heading h2{max-width:680px;font-size:3rem}.nova-heading>p{font-size:12px;margin-bottom:42px;opacity:.6}.doctor-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:25px}.doctor-grid article{border-radius:15px;overflow:hidden;background:#e9ede5}.doctor-grid img{height:300px;object-position:50% 28%}.doctor-grid article>div{padding:25px}.doctor-grid h3{font-size:21px}.doctor-grid article p{font-size:11px;margin:12px 0}.doctor-grid article>div>span{font-size:11px;opacity:.7}.care-team-note{padding:35px!important;background:#dee8d8!important;display:flex;flex-direction:column;justify-content:center}.care-team-note h3{font:400 32px/1.3 'Lora',serif}.care-team-note p{font-size:13px!important;line-height:1.9}.care-team-note .text-link{font-size:12px;margin-top:20px;width:fit-content}.nova-visit{display:grid;grid-template-columns:1fr 1fr;gap:10%}.nova-visit>div>p{font-size:14px;opacity:.7}.visit-steps{margin-top:30px}.visit-steps p{font-size:13px;border-bottom:1px solid var(--line);padding:17px 0}.visit-steps span{font-size:10px;margin-right:22px}.nova-visit .faq{font-size:14px}.nova-quote{background:#dce8df}.nova-quote blockquote{font:400 2.3rem/1.5 'Lora',serif;max-width:870px}.nova-address{font-size:13px;line-height:2}.demo-form{border-radius:18px}.demo-form h3{font-size:24px}.demo-form .button{border-radius:30px}input,select{border-radius:6px}@media(max-width:760px){.nova-top>span{display:none}.nova-top{justify-content:center;font-size:9px}.nova-nav .brand{font-size:25px}.nova-hero{grid-template-columns:1fr;padding:30px 0 45px;gap:30px}.nova-hero h1{font-size:3.25rem}.nova-portrait{width:85%;margin:auto}.nova-portrait>img{height:450px;border-radius:170px 170px 60px 60px}.care-card{left:-20px;padding:20px;bottom:10px}.nova-reassurance{font-size:9px;gap:20px;margin-top:28px}.nova-quicklinks{grid-template-columns:1fr}.nova-quicklinks a{border-right:0;border-bottom:1px solid var(--line);padding:20px 0}.care-services{grid-template-columns:1fr 1fr;gap:15px}.care-service{padding:24px 18px}.care-service h3{font-size:19px}.care-service p{font-size:11px}.care-icon{margin-bottom:25px}.service-more{font-size:10px;margin-top:25px}.nova-philosophy img{height:450px}.nova-philosophy h2{font-size:2.7rem}.nova-heading{display:block}.nova-heading h2{font-size:2.65rem}.nova-heading>p{margin-top:-20px}.doctor-grid{grid-template-columns:1fr}.doctor-grid img{height:390px}.nova-visit{grid-template-columns:1fr;gap:35px}.nova-quote blockquote{font-size:1.7rem}.nova-nav .nav-toggle{font-size:12px}}
`,js:`
const careDescriptions={'Primary care':'An ongoing relationship with a familiar care team. Routine appointments, preventive conversations and support with everyday concerns.','Mental wellbeing':'A thoughtful first conversation and a clear explanation of the support available. Your preferences remain part of every step.','Women’s health':'Personal, considered conversations with clinicians who take time to understand your questions and priorities.','Specialist care':'A connected approach to further expertise, helping you understand what to expect and what happens next.'};$$('[data-service]').forEach(b=>b.addEventListener('click',()=>{const value=b.dataset.service;$('select[name="department"]').value=value;showDialog(value,'<p>'+careDescriptions[value]+'</p><a class="button" href="#appointment">Plan a visit ↗</a>');}));
`});

writeSite({id:10,folder:'10-education',brand:'SUMMIT ACADEMY',industry:'Education & Learning',description:'Learn by doing. Find your people. Build what comes next.',category:'Professional',fonts:['Archivo','Lora'],color:'#f6f3e8',body:`
<div class="summit-top"><span>YOUR NEXT CHAPTER IS OPEN.</span><a href="#admissions">Explore the 2027 intake ↗</a></div>${nav('SUMMIT<br><span>ACADEMY</span>',[['Explore programs','programs'],['Life at Summit','life'],['Our faculty','faculty']],['Find your path','admissions'],'summit-nav','△')}
<main id="main"><section class="hero summit-hero wrap"><div class="summit-hero-copy">${eye('Big ideas start with a little curiosity.')}<h1>Your potential.<br><span>No ceiling.</span></h1><p>Practical learning. Inspiring people. A place to discover what you’re capable of — and go a little further.</p>${link('Find your program','#programs')}<div class="summit-date"><strong>2027</strong><span>APPLICATIONS<br>NOW OPEN</span></div></div><div class="summit-hero-photo">${img('education-hero','Students collaborating and learning together on campus','',true)}<span class="summit-sticker">MAKE<br>YOUR<br><b>MARK.</b></span><span class="photo-note">REAL PEOPLE. NEW POSSIBILITIES.</span></div></section>
<section class="summit-proof"><div class="wrap">${stats([['94%','Graduate progression rate'],['18:1','Student-to-mentor ratio'],['30+','Hands-on programs'],['ONE','Extraordinary community']])}</div></section>
<section class="section wrap" id="programs"><div class="summit-heading">${head('Where will curiosity take you?','Find your kind of next.')}<label class="course-search">Search programs<input type="search" id="course-search" placeholder="Design, business, technology..."></label></div><div class="course-grid">${[['DESIGN & CREATIVITY','Digital Design','12 months','Build meaningful digital experiences, from your first sketch to a finished portfolio.','design'],['BUSINESS & LEADERSHIP','Future Business','18 months','Think strategically, build confidently and learn how real organizations work.','business'],['TECHNOLOGY & INNOVATION','Creative Technology','12 months','Turn code, curiosity and creative thinking into things people can use.','technology'],['COMMUNICATION & CULTURE','Media & Storytelling','12 months','Find your voice and create stories worth paying attention to.','media']].map(([label,t,d,desc,cat],i)=>`<article class="course-card course-${i}" data-course-text="${(t+' '+desc+' '+cat).toLowerCase()}"><div><span>${label}</span><span>0${i+1}</span></div><h3>${t}</h3><p>${desc}</p><div class="course-bottom"><span>${d} · Full-time</span><button data-course="${t}" aria-label="Explore ${t}">↗</button></div></article>`).join('')}</div><p id="course-status" role="status" class="course-status">4 pathways to explore</p></section>
<section class="summit-life section" id="life"><div class="wrap split">${img('education-detail','University students studying together on campus steps')}<div>${head('There’s more to it than a classroom.','Find your people.<br>Find your momentum.','Debate a big idea over coffee. Build something with someone new. Join a club you never knew you needed. At Summit, the best parts of learning often happen between the lessons.')}<div class="campus-tags"><span>Creative studios</span><span>Industry projects</span><span>Student societies</span><span>Mentor sessions</span></div>${link('Visit Summit','#admissions','text-link')}</div></div></section>
<section class="section wrap" id="faculty">${head('Learn from people who do.','Real experience.<br>Generously shared.')}<div class="faculty-grid"><article><span class="faculty-number">01</span><h3>Riya Mehta</h3><p>Design & Digital Experiences</p><span>Designer, creative director, and a believer in making before overthinking.</span></article><article><span class="faculty-number">02</span><h3>Theo Williams</h3><p>Business & Entrepreneurship</p><span>Founder and strategist helping the next generation turn ideas into action.</span></article><article><span class="faculty-number">03</span><h3>Lena Fischer</h3><p>Creative Technology</p><span>Technologist exploring what happens where art, code and human needs meet.</span></article></div></section>
<section class="summit-story section"><div class="wrap"><span class="story-label">A SUMMIT STORY / 01</span><blockquote>“I arrived with a lot of questions.<br>I left with <em>a direction.</em>”</blockquote><div class="student-credit"><span>AK</span><p>Alex Kim<br><small>Digital Design, Class of 2025</small></p></div><p class="student-story">A live project became a portfolio piece. A portfolio piece opened a door. Alex now works with an independent studio designing tools for local communities.</p></div></section>
<section class="section wrap"><div class="summit-heading">${head('Built around your next chapter','Why Summit?')}</div>${cards([['LEARN BY DOING','Make something real.','Work on practical briefs, get honest feedback and build a portfolio that tells your story.'],['STAY CONNECTED','Open doors early.','Meet mentors, collaborate with industry partners and find the people who see your potential.'],['GROW WITH SUPPORT','Someone in your corner.','Personal tutors, career conversations and a community that helps you keep going.']])}</section>
<section class="section wrap split"><div>${head('A few useful answers.','Start with curiosity.')}<p>And bring every question you have.</p></div>${faq([['Do I need prior experience?','Our foundation pathways are designed for curious beginners. Advanced pathways would list their individual entry criteria in a production admissions system.'],['Can I visit before deciding?','The enquiry form below includes a campus visit option. This fictional academy demonstrates an admissions journey, so no real visit is booked.'],['What support is available?','The concept includes personal mentoring, learning support and career guidance as part of the student experience.']])}</section>
<section class="section summit-admissions" id="admissions"><div class="wrap split"><div>${eye('There’s a place for your ambition.')}<h2>What will<br><span>you do next?</span></h2><p>Tell us what sparks your interest.<br>Let’s explore where it could lead.</p></div>${form('Take the first step',select('I’m interested in',['Digital Design','Future Business','Creative Technology','Media & Storytelling','A campus visit'],'program')+select('Your next intake',['January 2027','September 2027'],'intake'),'Preview my enquiry')}</div></section></main>`,css:`
:root{--bg:#f7f5ec;--ink:#342652;--accent:#5636a7;--line:#34265230;--panel:#eeebf4;--body:'Archivo',sans-serif;--display:'Archivo',sans-serif;--weight:600;--button-ink:#fff}.summit-top{background:#382858;color:#f6f0dc;display:flex;justify-content:space-between;padding:10px 5%;font-size:9px;letter-spacing:.09em}.summit-top a{color:#e8ed79}.summit-nav .brand{font-size:22px;line-height:.9;display:block;letter-spacing:-.055em;position:relative;padding-left:40px}.summit-nav .brand-symbol{position:absolute;left:0;top:-3px;font-size:40px}.summit-nav .brand span:not(.brand-symbol){font-size:10px;letter-spacing:.17em;font-weight:400}.summit-nav nav{font-size:12px}.summit-nav .nav-cta{background:var(--accent);color:white;border:0}.summit-hero{display:grid;grid-template-columns:1fr 1fr;gap:5%;align-items:center;padding:45px 0 90px}.summit-hero h1{font-size:clamp(3.5rem,5.7vw,6.1rem);line-height:1.04;letter-spacing:-.07em}.summit-hero h1>span{color:var(--accent);display:inline-block;position:relative}.summit-hero h1>span:after{content:'';position:absolute;bottom:-5px;left:0;right:0;height:9px;background:#e0e677;z-index:-1;transform:rotate(-2deg)}.summit-hero p:not(.eyebrow){font-size:14px;line-height:1.9;max-width:410px;margin:30px 0}.summit-hero-photo{position:relative;padding:20px 0 30px}.summit-hero-photo img{height:570px;object-position:48% center;border-radius:7px 7px 80px 7px;transform:rotate(3deg)}.summit-sticker{position:absolute;bottom:5px;left:-30px;background:#e6ea7b;padding:25px 35px;font-size:28px;font-weight:600;line-height:.98;letter-spacing:-.05em;transform:rotate(-8deg)}.summit-sticker b{font-weight:700}.photo-note{position:absolute;right:20px;top:38px;color:#fff;font-size:8px;letter-spacing:.08em;text-shadow:0 1px 10px #000}.summit-date{display:flex;align-items:center;gap:15px;margin-top:40px}.summit-date strong{font-size:36px;letter-spacing:-.05em}.summit-date span{font-size:9px;line-height:1.6;letter-spacing:.07em}.summit-proof{background:#eae6f1}.summit-proof .stats{border:0}.summit-proof strong{font-size:3.2rem;font-weight:500}.summit-proof span{font-size:11px}.summit-heading{display:flex;justify-content:space-between;align-items:end;gap:45px}.summit-heading h2{font-size:3.5rem}.course-search{margin-bottom:42px;min-width:275px;font-size:10px}.course-search input{font-size:12px;background:transparent}.course-grid{display:grid;grid-template-columns:1fr 1fr;gap:25px}.course-card{background:#e9e6f3;padding:35px;transition:transform .3s}.course-card:hover{transform:translateY(-4px)}.course-1{background:#e6e9c6}.course-2{background:#dce7e6}.course-3{background:#efdcd1}.course-card>div:first-child{display:flex;justify-content:space-between;gap:20px;font-size:9px;letter-spacing:.08em}.course-card h3{font-size:2.15rem;margin:40px 0 20px}.course-card p{font-size:13px;line-height:1.9;max-width:350px;opacity:.8}.course-bottom{display:flex;justify-content:space-between;align-items:center;margin-top:40px;padding-top:20px;border-top:1px solid #34265230}.course-bottom>span{font-size:11px}.course-bottom button{background:transparent;border:1px solid #34265260;border-radius:50%;height:38px;width:38px;font-size:20px}.course-status{font-size:11px;opacity:.6;margin-top:25px}.summit-life{background:#382858;color:#f9f4e5;--line:#fff4}.summit-life img{height:610px;border-radius:150px 150px 5px 5px}.summit-life h2{font-size:3.5rem;line-height:1.15}.summit-life p{font-size:14px}.campus-tags{display:flex;flex-wrap:wrap;gap:9px;margin:25px 0}.campus-tags span{font-size:10px;border:1px solid #ffffff50;padding:7px 12px}.summit-life .text-link{color:#e6ea7b;margin-top:10px;font-size:12px}.faculty-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:40px}.faculty-number{font:italic 65px 'Lora',serif;color:#ad9dcd;display:block;margin-bottom:30px}.faculty-grid h3{font-size:25px}.faculty-grid p{font-size:11px;margin:15px 0}.faculty-grid article>span:last-child{font-size:13px;line-height:1.9;opacity:.7}.summit-story{background:#e9ed89}.story-label{font-size:10px;letter-spacing:.1em}.summit-story blockquote{font-size:clamp(2.4rem,4.2vw,4.5rem);font-weight:500;line-height:1.3;letter-spacing:-.045em;margin:40px 0}.summit-story blockquote em{font-family:'Lora',serif;font-weight:400}.student-credit{display:flex;align-items:center;gap:15px}.student-credit>span{width:50px;height:50px;display:grid;place-items:center;background:#342652;color:#e9ed89;border-radius:50%;font-size:14px}.student-credit p{font-size:13px}.student-credit small{font-size:10px;opacity:.7}.student-story{font-size:13px;line-height:1.9;max-width:570px;margin-top:30px}.cards article{border:0;border-top:2px solid var(--line);padding:30px 0}.cards{gap:45px}.cards h3{font-size:26px}.summit-admissions{background:#e8e4ef}.summit-admissions h2{font-size:5rem}.summit-admissions h2>span{color:var(--accent)}.summit-admissions .demo-form{background:#f7f5ec}.summit-admissions p{font-size:14px}.summit-admissions .demo-form p{font-size:12px}@media(max-width:760px){.summit-top{font-size:8px}.summit-hero{grid-template-columns:1fr;padding:25px 0 50px;gap:25px}.summit-hero h1{font-size:3.75rem}.summit-hero-photo{width:91%;margin:auto;padding-bottom:35px}.summit-hero-photo img{height:430px}.summit-sticker{left:-15px;bottom:5px;font-size:25px;padding:20px 28px}.summit-heading{display:block}.summit-heading h2{font-size:2.7rem}.course-search{margin-top:-15px;margin-bottom:28px}.course-grid{grid-template-columns:1fr}.course-card{padding:28px}.course-card h3{font-size:2rem;margin-top:30px}.summit-life img{height:480px}.summit-life h2{font-size:2.7rem}.faculty-grid{grid-template-columns:1fr;gap:35px}.faculty-grid article{border-bottom:1px solid var(--line);padding-bottom:25px}.faculty-number{float:left;font-size:45px;margin:0 28px 30px 0}.summit-story blockquote{font-size:2.4rem}.summit-admissions h2{font-size:3.5rem}.summit-proof strong{font-size:2.6rem}.summit-date{margin-top:25px}}
`,js:`
$('#course-search').addEventListener('input',e=>{const value=e.target.value.toLowerCase().trim();let count=0;$$('.course-card').forEach(card=>{card.hidden=!card.dataset.courseText.includes(value);if(!card.hidden)count++;});$('#course-status').textContent=count?count+' '+(count===1?'pathway':'pathways')+' to explore':'No programs match. Try design, business, technology or media.';});$$('[data-course]').forEach(b=>b.addEventListener('click',()=>{const name=b.dataset.course;$('select[name="program"]').value=name;showDialog(name,'<p>A practical pathway built around projects, personal feedback and conversations with people working in the field.</p><p>Your week combines taught sessions, studio time and collaborative briefs. You finish with a body of work that shows how you think and what you can do.</p><a class="button" href="#admissions">Explore your next step ↗</a>');}));
`});
finish();
